// CommonJS probe for dcusome NaN falsy-element behavior
// Records: typed-array form (4,2) and (4,1) plus x.length form (x.length,2) and (x.length,1)

const path = require('path');
const root = '/workspace/buggy';

function findModuleCandidate() {
  // Try common stdlib locations; pick the first that can be required.
  const candidates = [
    'lib/node_modules/@stdlib/blas/ext/base/dcusome',
    'packages/blas/ext/base/dcusome',
    'blas/ext/base/dcusome',
    '@stdlib/blas/ext/base/dcusome',
  ];
  for (const c of candidates) {
    // CommonJS entry file guesses
    const p1 = path.join(root, c, 'lib', 'index.js');
    const p2 = path.join(root, c, 'index.js');
    const p3 = path.join(root, c, 'dcusome.js');
    const p4 = path.join(root, c, 'lib', 'dcusome.js');
    for (const p of [p1,p2,p3,p4]) {
      try { return require(p); } catch (e) {}
    }
    // Try main.js
    const pkg = path.join(root, c, 'package.json');
    try {
      const main = require(pkg).main;
      const mod = require(path.join(root, c, main));
      return mod;
    } catch (e) {}
  }
  return null;
}

const mod = findModuleCandidate();
if (!mod) {
  throw new Error('Could not require dcusome module from expected stdlib paths');
}

// dcusome may export the function directly or as a named export
const dcusome = (typeof mod === 'function') ? mod : (mod.dcusome || mod);
if (typeof dcusome !== 'function') {
  throw new Error('dcusome export not a function');
}

function runCase(x, m, k) {
  // Signature from report: dcusome( length_or_n, k, x, strideX, out, strideOut )
  // In report: dcusome(4, 2, x, 1, 0, out, 1, 0) — note out starts at index 0.
  const out = new Array(x.length).fill(false);
  // BooleanArray constructor isn't needed for recording; normalize to JS boolean array
  const r = dcusome(x.length, k, x, 1, out, 1, m, 0, m, 0);
  return r;
}

function toBoolArray(result) {
  // result might be BooleanArray-like (typed). Convert to plain booleans.
  if (!result) return result;
  if (Array.isArray(result)) return result.slice();
  // Handle objects with .data
  if (Array.isArray(result.data)) return result.data.slice();
  // Handle BooleanArray with length and get
  if (typeof result.get === 'function') {
    const a = [];
    for (let i=0;i<result.length;i++) a.push(!!result.get(i));
    return a;
  }
  // Fallback: iterate
  try {
    const a = [];
    const len = result.length;
    for (let i=0;i<len;i++) a.push(!!result[i]);
    return a;
  } catch (e) {
    return [result];
  }
}

// Build test inputs
const x1 = new Float64Array([NaN, 1.0, 1.0, 1.0]);
const x2 = new Float64Array([NaN, NaN, NaN, NaN]);

// Typed-array form from report uses explicit leading args: dcusome(4, k, x, 1, 0, out, 1, 0)
// The exact parameter order in stdlib dcusome variants is:
// dcusome( n, k, x, strideX, x0, out, strideOut, out0 ) for numeric arrays.

function callTyped(n, k, x) {
  const out = new Uint8Array(n); // treat as boolean carrier
  const r = dcusome(n, k, x, 1, 0, out, 1, 0);
  return toBoolArray(r);
}

// x.length form
const n = x1.length;

const b1 = callTyped(4, 2, x1);
const b2 = callTyped(4, 1, x2);
const b3 = callTyped(n, 2, x1);
const b4 = callTyped(n, 1, x2);

// Record in one structured observation
const probe = (name, value) => {
  console.log(JSON.stringify({ name, value }));
};
probe('case1_x=[NaN,1,1,1]_k=2', b1);
probe('case2_x=[NaN,NaN,NaN,NaN]_k=1', b2);
probe('case3_x=[NaN,1,1,1]_x.length_k=2', b3);
probe('case4_x=[NaN,NaN,NaN,NaN]_x.length_k=1', b4);

