const path = require('path');
const x = require('./src/index.js');
const dcusome = x.dcusome;
const out = new x.BooleanArray(4);
const arrNaNOnes = new Float64Array([NaN, 1.0, 1.0, 1.0]);
const arrAllNaN = new Float64Array([NaN, NaN, NaN, NaN]);
const i = 1;
const one = 1;
const zero = 0;
const __numagentCases = [["dcusome( 4, 2, new Float64Array([ NaN, 1.0, 1.0, 1.0 ]), 1, 0, out, 1, 0 ) with out = new BooleanArray(4)", "dcusome( 4, 2, new Float64Array([ NaN, 1.0, 1.0, 1.0 ]), 1, 0, out, 1, 0 ) with out = new BooleanArray(4)", [], "new BooleanArray([ false, false, true, true ])"], ["dcusome( 4, 1, new Float64Array([ NaN, NaN, NaN, NaN ]), 1, 0, out, 1, 0 ) with out = new BooleanArray(4)", "dcusome( 4, 1, new Float64Array([ NaN, NaN, NaN, NaN ]), 1, 0, out, 1, 0 ) with out = new BooleanArray(4)", [], "new BooleanArray([ false, false, false, false ])"], ["dcusome( x.length, 2, new Float64Array([ NaN, 1.0, 1.0, 1.0 ]), 1, out, 1 ) with out = new BooleanArray(4) (test.dcusome.js form)", "dcusome( x.length, 2, new Float64Array([ NaN, 1.0, 1.0, 1.0 ]), 1, out, 1 ) with out = new BooleanArray(4)", [], "new BooleanArray([ false, false, true, true ])"], ["dcusome( x.length, 1, new Float64Array([ NaN, NaN, NaN, NaN ]), 1, out, 1 ) with out = new BooleanArray(4) (test.dcusome.js form)", "dcusome( x.length, 1, new Float64Array([ NaN, NaN, NaN, NaN ]), 1, out, 1 ) with out = new BooleanArray(4)", [], "new BooleanArray([ false, false, false, false ])"]];
for (const [__name, __expr, __binds, __want] of __numagentCases) {
  try {
    for (const __b of __binds) { eval("var " + __b); }
    probe(__name, eval(__expr));
  } catch (e) {
    probe(__name, "__error__: " + ((e && e.name) ? e.name : "Error") + ": " +
          String((e && e.message) ? e.message : e).slice(0, 200));
  }
  if (__want) {
    try { probe("expected::" + __name, eval(__want)); } catch (e) { }
  }
}

